UPDATE public."BAT_タスク実行情報"
   SET "状態" = 'RUNNING', "開始時刻" = CURRENT_TIMESTAMP, "更新日時" = CURRENT_TIMESTAMP
 WHERE "実行ID" = #{executionId}

mapper.select:
SELECT "実行ID","タスクコード","状態","予定時刻","開始時刻","終了時刻","メッセージ","依頼者","登録日時","更新日時"
  FROM public."BAT_タスク実行情報"
 WHERE "実行ID" = #{executionId}

SELECT "実行ID","タスクコード","状態","予定時刻","開始時刻","終了時刻","メッセージ","依頼者","登録日時","更新日時"
  FROM public."BAT_タスク実行情報"


        "タスクコード" = #{taskCode}


 ORDER BY "実行ID" DESC
 LIMIT #{limit}

SELECT count(*)
  FROM public."BAT_タスク実行情報"
 WHERE "タスクコード" = #{taskCode}
   AND "状態" = #{status}
